// Golden training score (plan 02-03, TRUST-10, D-20, Pitfalls 8 and 9). Scores the 16 training units of
// test/golden/units.jsonl from the committed collector snapshot test/golden/inputs/inputs.jsonl with the shipped
// tier rules, and reports agreement per dimension as test diagnostics. The snapshot holds metadata only and is
// regenerated by hand with scripts/golden-inputs.mjs (test/golden/README.md, "Scoring (rigorscope)").
//
// This file reads only the training labels. The held-out labels are read by one acceptance test alone, which reports
// counts only; nothing here may be tuned against them. Floors are regression guards on the training file, measured
// when they were set, not targets. Timing is reported with no floor (Pitfall 9: it is a judgment from commit order).
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { join } from 'node:path';

const GOLDEN = fileURLToPath(new URL('./', import.meta.url));
const TRAINING = join(GOLDEN, 'units.jsonl');
const MANIFEST = join(GOLDEN, 'inputs', 'manifest.json');
const INPUTS = join(GOLDEN, 'inputs', 'inputs.jsonl');
const scoreModule = () => import(pathToFileURL(join(GOLDEN, 'score.mjs')).href);

// Regression guard: tier value agreement on the 16 training units. The one expected miss is 261022-g5g, whose tier
// is declared only in a CONTEXT section and a SUMMARY body line, outside the D-01 places (amendment Q6).
export const TIER_VALUE_FLOOR = 15;
export const TIER_VALUE_MISSES = Object.freeze(['repo-c:quick:261022-g5g']);
export const TRAINING_UNITS = 16;
export const TRAINING_TIMING_N = 7;
// Regression guards on the training file for the shipped risk table (risk-rules-2026-10-30), measured at the commit
// that set them (plan 02-03 Task 2 step 8: Jaccard 0.536 and exact 5 of 16, the research v1 measurement); never
// targets, and never raised by editing the rules. The Jaccard floor is the measured mean rounded down to two decimals.
export const RISK_JACCARD_FLOOR = 0.53;
export const RISK_EXACT_FLOOR = 5;
// Golden tags with no D-05 tag on the training file (validation, datastore): counted, never scored.
export const TRAINING_UNMAPPED_GOLD_TAGS = 2;
const rulesModule = () => import(pathToFileURL(join(GOLDEN, '..', '..', 'src', 'units', 'risk-rules.mjs')).href);
const README = join(GOLDEN, 'README.md');
const GOLDEN_TAGS = ['gate-or-hook', 'global-config', 'push', 'credentials', 'security', 'parser', 'script', 'docs', 'datastore',
  'validation', 'business-logic'];

const compareBytes = (a, b) => Buffer.compare(Buffer.from(a), Buffer.from(b));
const manifestKey = (u) => `${u.repo}\u0000${u.kind}\u0000${u.native_id}`;
const readLines = (file) => readFileSync(file, 'utf8').split('\n').filter((l) => l !== '').map((l) => JSON.parse(l));

function loadAll() {
  assert.ok(existsSync(MANIFEST), 'the golden inputs manifest exists');
  assert.ok(existsSync(INPUTS), 'the golden inputs snapshot exists');
  const manifest = JSON.parse(readFileSync(MANIFEST, 'utf8'));
  return { manifest, inputs: readLines(INPUTS), labels: readLines(TRAINING) };
}

describe('golden inputs snapshot', () => {
  it('the manifest lists 21 unique units sorted bytewise, and the snapshot has one row per entry in that order', () => {
    const { manifest, inputs } = loadAll();
    assert.equal(manifest.schema, 'rigorscope.golden-manifest/1');
    assert.equal(manifest.units.length, 21);
    const keys = manifest.units.map(manifestKey);
    assert.equal(new Set(keys).size, 21, 'the manifest entries are unique');
    assert.deepEqual([...keys].sort(compareBytes), keys, 'the manifest is sorted bytewise');
    for (const u of manifest.units) {
      assert.deepEqual(Object.keys(u), ['repo', 'kind', 'native_id']);
      assert.ok(['quick', 'plan'].includes(u.kind));
    }
    assert.deepEqual(inputs.map(manifestKey), keys);
    for (const r of inputs) assert.equal(r.schema, 'rigorscope.golden-inputs/1');
  });

  it('every path value is repo-relative, starts with ~ or is written from $HOME, never absolute', () => {
    const { inputs } = loadAll();
    const paths = [];
    for (const r of inputs) {
      if (!r.located) continue;
      paths.push(r.dir_rel, ...r.artifacts.map((a) => a.rel_path), ...(r.files_modified ?? []));
      for (const c of r.commits ?? []) paths.push(...c.files.map((f) => f.path));
    }
    assert.ok(paths.length > 0);
    for (const p of paths) {
      assert.equal(typeof p, 'string');
      assert.ok(!p.startsWith('/'), 'an absolute path in the snapshot');
      assert.ok(!/^[A-Za-z]:/.test(p), 'a drive path in the snapshot');
      assert.ok(!p.split('/').includes('..'), 'a parent segment in the snapshot');
      assert.ok(!p.startsWith('~') || p === '~' || p.startsWith('~/'), 'a ~user path in the snapshot');
    }
  });
});

describe('golden training score', () => {
  it('every training unit has a located row and the tier value agreement holds its floor', async (t) => {
    const { scoreGolden, formatScore, goldenKind, unitKeyOf } = await scoreModule();
    const { inputs, labels } = loadAll();
    assert.equal(labels.length, TRAINING_UNITS);
    const located = new Set(inputs.filter((r) => r.located).map(unitKeyOf));
    for (const l of labels) {
      const key = unitKeyOf({ repo: l.unit.repo, kind: goldenKind(l.unit.kind), native_id: l.unit.native_id });
      assert.ok(located.has(key), `training unit ${key} has a located row`);
    }
    const score = scoreGolden({ labels, inputs });
    t.diagnostic(formatScore('training', score));
    assert.equal(score.units, TRAINING_UNITS);
    assert.equal(score.located, TRAINING_UNITS);
    assert.ok(score.tierValue.hit >= TIER_VALUE_FLOOR, `tier value ${score.tierValue.hit}/${score.tierValue.n}`);
    assert.deepEqual(score.tierValue.misses, [...TIER_VALUE_MISSES]);
    assert.equal(score.tierTiming.n, TRAINING_TIMING_N, 'timing is scored on the training units with a letter and a declared source');
  });
});

// The mapping table of test/golden/README.md "## Scoring (rigorscope)": golden tag -> D-05 tag or null.
function readmeMapping() {
  const text = readFileSync(README, 'utf8');
  const at = text.indexOf('\n## Scoring (rigorscope)\n');
  assert.ok(at !== -1, 'test/golden/README.md has a Scoring (rigorscope) section');
  const rest = text.slice(at + 1);
  const next = rest.indexOf('\n## ', 3);
  const section = next === -1 ? rest : rest.slice(0, next);
  const out = {};
  for (const line of section.split('\n')) {
    const cells = line.split('|').map((c) => c.trim().replace(/^`|`$/g, ''));
    if (cells.length < 4 || cells[0] !== '' || !/^[a-z][a-z-]*$/.test(cells[1])) continue;
    if (cells[1] === 'golden') continue;
    out[cells[1]] = cells[2] === '(none)' ? null : cells[2];
  }
  return out;
}

describe('golden risk tag mapping', () => {
  it('GOLDEN_TAG_MAP lists the eleven README tags with their dispositions and equals the README table', async () => {
    const { GOLDEN_TAG_MAP } = await scoreModule();
    assert.ok(GOLDEN_TAG_MAP && typeof GOLDEN_TAG_MAP === 'object', 'GOLDEN_TAG_MAP is exported');
    assert.deepEqual(Object.keys(GOLDEN_TAG_MAP).sort(), [...GOLDEN_TAGS].sort());
    assert.deepEqual({ ...GOLDEN_TAG_MAP }, {
      'gate-or-hook': 'gate-or-hook',
      'global-config': 'global-config',
      parser: 'parser',
      script: 'script',
      docs: 'docs',
      security: 'security',
      push: 'security',
      credentials: 'security',
      datastore: null,
      validation: null,
      'business-logic': null,
    });
    assert.ok(Object.isFrozen(GOLDEN_TAG_MAP));
    assert.equal(Object.getPrototypeOf(GOLDEN_TAG_MAP), null);
    assert.deepEqual(readmeMapping(), { ...GOLDEN_TAG_MAP });
  });

  it('every golden tag of the training file is a key of the map', async () => {
    const { GOLDEN_TAG_MAP } = await scoreModule();
    const { labels } = loadAll();
    for (const l of labels) for (const r of l.risk_class) assert.ok(Object.hasOwn(GOLDEN_TAG_MAP, r.tag), 'a training tag is missing from GOLDEN_TAG_MAP');
  });
});

describe('golden training risk score', () => {
  it('reports exact, Jaccard, unknown and unmapped counts and per-tag counts, above the recorded floors', async (t) => {
    const { scoreGolden, formatScore, formatTagLine } = await scoreModule();
    const { loadRiskRules } = await rulesModule();
    const { inputs, labels } = loadAll();
    const riskTable = loadRiskRules();
    const score = scoreGolden({ labels, inputs, riskTable });
    const line = formatScore('training', score);
    t.diagnostic(line);
    t.diagnostic(formatTagLine('training', score));
    assert.match(line, /^golden training: units=16 located=16 tier_value=\d+\/16 tier_timing=\d+\/7 risk_exact=\d+\/16 risk_jaccard=\d\.\d{3} risk_unknown=\d+ unmapped_gold_tags=2 rules=2026-10-30$/);
    assert.equal(score.risk.unmapped, TRAINING_UNMAPPED_GOLD_TAGS);
    assert.ok(score.risk.jaccardMean >= RISK_JACCARD_FLOOR, `risk Jaccard ${score.risk.jaccardMean}`);
    assert.ok(score.risk.exact.hit >= RISK_EXACT_FLOOR, `risk exact ${score.risk.exact.hit}`);
    assert.match(formatTagLine('training', score), /^golden training risk tags: docs tp=\d+ fp=\d+ fn=\d+; gate-or-hook tp=\d+ fp=\d+ fn=\d+; global-config .*; parser .*; script .*; security tp=\d+ fp=\d+ fn=\d+$/);
  });
});

describe('golden scorer edge cases', () => {
  const label = (repo, id, tags, value = 'none') => ({
    schema_version: 1, unit: { repo, kind: 'quick', native_id: id }, tier: { value, source: 'unknown' }, risk_class: tags.map((tag) => ({ tag })),
  });
  const input = (repo, id, filesModified, commits = []) => ({
    schema: 'rigorscope.golden-inputs/1', repo, kind: 'quick', native_id: id, located: true, dir_rel: `.planning/quick/${id}-x`, git: 'ok',
    artifacts: [], files_modified: filesModified, commits, dropped_paths: 0,
  });

  it('zero rows print ? for every ratio', async () => {
    const { scoreGolden, formatScore } = await scoreModule();
    const { loadRiskRules } = await rulesModule();
    assert.equal(formatScore('empty', scoreGolden({ labels: [], inputs: [], riskTable: loadRiskRules() })),
      'golden empty: units=0 located=0 tier_value=? tier_timing=? risk_exact=? risk_jaccard=? risk_unknown=0 unmapped_gold_tags=0 rules=2026-10-30');
  });

  it('empty versus empty is Jaccard 1; an unknown prediction is Jaccard 0 and counted; two tags mapping to one count once', async () => {
    const { scoreGolden } = await scoreModule();
    const { loadRiskRules } = await rulesModule();
    const riskTable = loadRiskRules();
    const one = (l, i) => scoreGolden({ labels: [l], inputs: [i], riskTable }).risk;
    const empty = one(label('r', '261001-aaa', []), input('r', '261001-aaa', ['test/a.test.mjs']));
    assert.equal(empty.jaccardMean, 1);
    assert.equal(empty.exact.hit, 1);
    const unknown = one(label('r', '261001-aaa', ['script']), input('r', '261001-aaa', null, []));
    assert.equal(unknown.jaccardMean, 0);
    assert.equal(unknown.unknown, 1);
    assert.equal(unknown.exact.hit, 0);
    assert.deepEqual(unknown.perTag.script, { tp: 0, fp: 0, fn: 1 });
    const both = one(label('r', '261001-aaa', ['push', 'credentials', 'security', 'validation']), input('r', '261001-aaa', ['src/auth.mjs']));
    assert.equal(both.jaccardMean, 1);
    assert.equal(both.exact.hit, 1);
    assert.equal(both.unmapped, 1);
    assert.deepEqual(both.perTag.security, { tp: 1, fp: 0, fn: 0 });
  });

  it('a golden tag missing from the map fails the score', async () => {
    const { scoreGolden } = await scoreModule();
    const { loadRiskRules } = await rulesModule();
    assert.throws(() => scoreGolden({ labels: [label('r', '261001-aaa', ['unheard-of'])], inputs: [input('r', '261001-aaa', [])], riskTable: loadRiskRules() }));
  });

  it('units with one native_id in two repos are distinct; an empty files_modified falls back to commit files', async () => {
    const { scoreGolden } = await scoreModule();
    const { loadRiskRules } = await rulesModule();
    const commits = [{ sha: 'a'.repeat(40), author_ms: 1, files: [{ path: 'hooks/h.mjs', status: 'A' }] }];
    const s = scoreGolden({
      labels: [label('x', '261001-aaa', ['gate-or-hook']), label('y', '261001-aaa', ['docs'])],
      inputs: [input('x', '261001-aaa', [], commits), input('y', '261001-aaa', ['README.md'])],
      riskTable: loadRiskRules(),
    });
    assert.equal(s.risk.exact.hit, 2);
  });
});
